10	/**
11	 * Process-wide signed-URL cache.
12	 *
13	 * `createSignedUrls` returns a NEW token every call, so re-signing the same file
14	 * yields a different URL — which the browser treats as a different image and
15	 * re-downloads. Measured on the generator: switching occasion produced 3 of 3
16	 * identical files and 0 of 3 identical URLs.
17	 *
18	 * Caching is safe because a signed URL is a capability for one path, and the
19	 * caller has already had to obtain that path through RLS to ask for it. The
20	 * cache grants nothing a caller could not mint for itself a line later.
21	 */
22	const cache: UrlCache = new Map();
