1	/**
2	 * The user's local calendar date, as `YYYY-MM-DD`.
3	 *
4	 * This is the key of the daily look set. It must be LOCAL: keyed on the UTC
5	 * date, the drop would roll over mid-evening for eastern users and mid-morning
6	 * for western ones. `en-CA` is used purely because it formats as YYYY-MM-DD.
7	 */
8	export function localDateFor(now: Date, timeZone: string): string {
9	  try {
10	    return new Intl.DateTimeFormat("en-CA", {
11	      timeZone,
12	      year: "numeric",
13	      month: "2-digit",
14	      day: "2-digit",
15	    }).format(now);
16	  } catch {
17	    // An unknown zone must never block generation — fall back to UTC.
18	    return now.toISOString().slice(0, 10);
19	  }
20	}
